from typing import List

class Solution:
    def longestOnes(self, nums: List[int], k: int) -> int:
        best = 0
        for left in range(len(nums)):
            zeros = 0
            for right in range(left, len(nums)):
                zeros += nums[right] == 0
                if zeros > k:
                    break
                best = max(best, right - left + 1)
        return best

